//-----------------------customize-----------------------
var isAlnum = function (ch) {
  return /^[0-9]$/i.test(ch);
};
var isUpperCase = function (n) {
  if (n >= "A" && n <= "Z") {
    return true;
  } else {
    return false;
  }
};

// check if char is letter
function isAlphabet(char) {
  if (typeof char !== "string") {
    return false;
  }
  // RegExp(正則表達式-匹配字串中的字元組合)
  return /^[a-z]+$/.test(char);
}

// check if char is num
function isNum(num) {
  return typeof num === number && isFinite(num);
}

var getRandomCharacter = function (length) { 
  var result = "";
  var symbols = "!@#$%^&*(){}[]=<>/.";
  for (var i = 0; i < length; i++) {
    result += symbols.charAt(Math.floor(Math.random() * symbols.length));
  }
  return result;
};
var randomNum = function (min, max) { // 3 upper case alphabet
  let num = [];
  for (var i = 0; i < 3; i++) {
    num.push(Math.floor(Math.random() * max) + min);
  }
  return num;
};
var randomNum4 = function (min, max) { //4 numbers generator
  let num = [];
  for (var i = 0; i < 4; i++) {
    num.push(Math.floor(Math.random() * max) + min);
  }
  return num;
};
//-------------------------------------------------------

//get the password from the form
function getThisPassword() {
  isMatch = 0;
  // get the value first
  var pwdElement = document.getElementById("pwd");
  passWord = pwdElement.value;
  // console.log(passWord); //!TEST
  // and call the function
  checkPasswordLenght(passWord);
}

function checkPasswordLenght(password) {
  //check password's lenght is enough
  if (password.length < 8) {
    //print
    document.getElementById("strength").innerHTML = "weak";
    document.getElementById("strength").style.color = "red";
  } else {
    // lenght is enough => call the function
    isPasswordStrong(password);
  }
  judge();
}

function isPasswordStrong(password) {
  //get first and second letter from the string
  var pwdSlice = password.slice(0, 2).toLowerCase();
  // console.log(pwdSlice); //!TEST
  if (isAlphabet(pwdSlice)) {
    //d_index is index of dataMap this array
    try {
      // if pwdSlice like double alphaber
      d_index = dataMap.indexOf(pwdSlice);
    } catch {
      // if pwdSlice like alphabet+num/sc ex: a1
      // so we get the first one char at this string
      pwdSilce = password.slice(0, 1).toLowerCase();
      // console.log(pwdSlice); //!TEST
      d_index = dataMap.indexOf(pwdSlice);
    }
    // console.log(d_index); //!TEST
  }
  // is not the alphabet => is number or special char
  else {
    d_index = dataMap.indexOf(pwdSlice);
  }

  mapPwdList(d_index);
}

function mapPwdList(index) {
  const arrMap = dataMap[index + 1];
  // console.log(arrMap); //!TEST
  for (var i = 0; i < arrMap.length; i++) {
    // console.log(arrMap[i]); //!TEST
    // console.log(passWord.match(arrMap[i])); //!TEST

    if (passWord.indexOf(arrMap[i]) !== -1) {
      isMatch += 1;
    }
  }
  console.log(isMatch); //!TEST
  judge();
}

function judge() {
  strength = "weak";

  if (isMatch >= 2 || passWord.length < 8) {
    document.getElementById("strength").style.color = "red";
    document.getElementById("suggestion").style.color = "red";
    strength = "weak";
  }
  else {
    wordArray = passWord.split("");
    var pwdLen = passWord.length

    // is medium
    for (var i = 0; i < pwdLen; i++) {
      console.log(isAlnum(wordArray[i]));
      if (isAlnum(wordArray[i])) {
        for (var j = 0; j <pwdLen; j++) {
          if (isUpperCase(wordArray[j])) {
            strength = "medium";
            document.getElementById("strength").style.color = "orange";
          }
        }
      }
    }
  }

  if (strength == "medium" && passWord.length >= 12) {
    strength = "strong";
    document.getElementById("strength").style.color = "yellow";
  }
  if (strength == "medium") {
    document.getElementById("suggestion").innerHTML = "Suggestion:";
    document.getElementById("suggestion").style.color = "black";
  } else if (strength == "strong") {
    document.getElementById("suggestion").innerHTML = "";
  } else if (strength == "weak") {
    document.getElementById("suggestion").innerHTML = "密碼強度不夠";
    document.getElementById("strength").style.color = "red";
    document.getElementById("suggestion").style.color = "red";
  }
  document.getElementById("strength").innerHTML = strength;



  //---------------------print and suggestion generator-------------------------
  if (strength == "medium") {
    for (var x = 0; x < 3; x++) {
      word1array = wordArray;
      final = "";
      shuffledarray = [];
      numarray = [];
      temparray = [];
      finalarray = [];
      ss = [];
      for (var i = 0; i < 3; i++) {
        temp[i] = randomNum(0, 7)[i];
        word1array[temp[i]] = word1array[temp[i]].toUpperCase();
      }

      for (var i = 0; i < 8; i++) {
        temparray[i] = wordArray[i];
      }
      numarray = randomNum4(0, 10);
      shuffledarray = temparray.concat(numarray);
      shuffledarray.push(getRandomCharacter(1));
      finalarray = shuffledarray.sort((a, b) => 0.5 - Math.random());
      for (var i = 0; i < 12; i++) {
        final += finalarray[i];
      }
      ss.push(final);
      if (x == 0) {
        document.getElementById("s1").innerHTML = ss[0];
      } else if (x == 1) {
        document.getElementById("s2").innerHTML = ss[0];
      } else if (x == 2) {
        document.getElementById("s3").innerHTML = ss[0];
      }

      word1array = [];
    }
  } else {
    document.getElementById("s1").innerHTML = "";
    document.getElementById("s2").innerHTML = "";
    document.getElementById("s3").innerHTML = "";
  }
}
